class ParticleNetwork {
  constructor(canvas, options = {}) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.particles = [];
    this.mouseParticles = [];
    
    // Default options
    this.options = {
      particleColors: ['#FF5F1F', '#FF8C00', '#39FF14'],
      velocity: 0.5,
      density: 15000,
      netLineDistance: 200,
      netLineColor: '#FF5F1F',
      ...options
    };
    
    // Set canvas size
    this.resize();
    
    // Initialize particles
    this.createParticles();
    
    // Bind events
    window.addEventListener('resize', () => this.resize());
  }
  
  createParticles() {
    const particleCount = (this.canvas.width * this.canvas.height) / this.options.density;
    
    for (let i = 0; i < particleCount; i++) {
      this.particles.push({
        x: Math.random() * this.canvas.width,
        y: Math.random() * this.canvas.height,
        velocity: {
          x: (Math.random() - 0.5) * this.options.velocity,
          y: (Math.random() - 0.5) * this.options.velocity
        },
        color: this.options.particleColors[Math.floor(Math.random() * this.options.particleColors.length)]
      });
    }
  }
  
  resize() {
    this.canvas.width = window.innerWidth;
    this.canvas.height = window.innerHeight;
  }
  
  drawParticles() {
    this.particles.forEach(particle => {
      // Update position
      particle.x += particle.velocity.x;
      particle.y += particle.velocity.y;
      
      // Bounce off edges
      if (particle.x > this.canvas.width || particle.x < 0) particle.velocity.x *= -1;
      if (particle.y > this.canvas.height || particle.y < 0) particle.velocity.y *= -1;
      
      // Draw particle
      this.ctx.beginPath();
      this.ctx.fillStyle = particle.color;
      this.ctx.globalAlpha = 0.7;
      this.ctx.arc(particle.x, particle.y, 1.5, 0, Math.PI * 2);
      this.ctx.fill();
    });
  }
  
  drawLines() {
    for (let i = 0; i < this.particles.length; i++) {
      for (let j = i + 1; j < this.particles.length; j++) {
        const dx = this.particles[i].x - this.particles[j].x;
        const dy = this.particles[i].y - this.particles[j].y;
        const distance = Math.sqrt(dx * dx + dy * dy);
        
        if (distance < this.options.netLineDistance) {
          this.ctx.beginPath();
          this.ctx.strokeStyle = this.options.netLineColor;
          this.ctx.globalAlpha = 0.7 * (1 - distance / this.options.netLineDistance);
          this.ctx.lineWidth = 1;
          this.ctx.moveTo(this.particles[i].x, this.particles[i].y);
          this.ctx.lineTo(this.particles[j].x, this.particles[j].y);
          this.ctx.stroke();
        }
      }
    }
  }
  
  animate() {
    this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
    this.drawParticles();
    this.drawLines();
    requestAnimationFrame(() => this.animate());
  }
  
  start() {
    this.animate();
    return this;
  }
}